"""Text-to-SQL harness: grounded draft -> execute + shape checks -> targeted repair.

Contract (fixed): solve(task, env) -> {"sql": str}
  task  {"id", "db_id", "question", "hint"}
  env.chat(messages, max_tokens=None) -> str     capped per task: env.max_calls
  env.schema(db_id) -> str
  env.execute(sql, max_rows=20) -> dict          {ok, columns, rows, n_rows, error}
  env.descriptions(db_id) -> str
  env.prompt(name) -> str
  env.config -> dict
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
LITERAL = re.compile(r"'([^']*)'")
STOP = set(
    """select from where and or not in is null as on join left right inner outer full cross
    union all except intersect distinct group by order having limit offset asc desc count sum
    avg min max cast int integer real text float case when then else end like between exists
    lower upper substr length trim coalesce ifnull round abs total group_concat instr replace
    t1 t2 t3 t4 t5 a b c d e f g h i j k l m n o p q r s t u v w x y z asc desc with recursive
    true false date time strftime julianday""".split()
)

AGG_CALL = re.compile(r"\b(count|sum|avg|min|max|total|group_concat)\s*\(", re.I)
VAGUE_Q = re.compile(
    r"\b(details?|information|info|records?|data|everything|all about)\b", re.I
)


def extract_sql(text):
    blocks = [b.strip() for b in SQL_BLOCK.findall(text or "") if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    txt = (text or "").strip()
    m = re.findall(r"(?is)\b(select|with)\b.*", txt)
    if m:
        return m[-1].rstrip(";").strip()
    return txt.rstrip(";").strip()


def _tables(schema):
    """table name -> list of column names, from CREATE statements."""
    out = {}
    for m in re.finditer(
        r"CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?[\"'`\[]?([A-Za-z_0-9]+)[\"'`\]]?\s*\((.*?)\)\s*;",
        schema or "",
        re.S | re.I,
    ):
        name, body = m.group(1), m.group(2)
        cols = []
        depth = 0
        cur = ""
        parts = []
        for ch in body:
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
            if ch == "," and depth == 0:
                parts.append(cur)
                cur = ""
            else:
                cur += ch
        parts.append(cur)
        for p in parts:
            p = p.strip()
            if not p:
                continue
            first = p.split()[0].strip('"`[]\'')
            if first.lower() in ("primary", "foreign", "unique", "check", "constraint"):
                continue
            cols.append(first)
        out[name] = cols
    return out


def _sample_values(env, schema, sql, budget=3):
    """Show real stored values for columns referenced near a string literal."""
    tabs = _tables(schema)
    low = sql.lower()
    used = [t for t in tabs if re.search(r"\b" + re.escape(t.lower()) + r"\b", low)]
    lits = [v.strip() for v in LITERAL.findall(sql) if v.strip()]
    targets = []
    for t in used:
        for col in tabs[t]:
            cl = col.lower()
            if cl in STOP:
                continue
            mentioned = re.search(r"\b" + re.escape(cl) + r"\b", low)
            if not mentioned:
                continue
            score = 0
            if re.search(re.escape(cl) + r"\s*(=|like|!=|<>|in)", low):
                score += 2
            if any(w and w in cl for lit in lits for w in re.findall(r"[a-zA-Z_]{3,}", lit.lower())):
                score += 3
            if score:
                targets.append((score, t, col))
    targets.sort(reverse=True)
    lines = []
    for _, t, col in targets[:budget]:
        q = 'SELECT DISTINCT "%s" FROM "%s" WHERE "%s" IS NOT NULL LIMIT 8' % (col, t, col)
        try:
            r = env.execute(q, max_rows=8)
        except Exception:
            continue
        if r.get("ok") and r.get("rows"):
            vals = [str(x[0])[:60] for x in r["rows"]]
            lines.append("%s.%s sample values: %s" % (t, col, " | ".join(vals)))
    return "\n".join(lines)


def _split_top(s):
    parts, depth, cur, quote = [], 0, "", None
    for ch in s:
        if quote:
            cur += ch
            if ch == quote:
                quote = None
            continue
        if ch in "'\"`":
            quote = ch
            cur += ch
            continue
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
        if ch == "," and depth == 0:
            parts.append(cur)
            cur = ""
        else:
            cur += ch
    parts.append(cur)
    return [p.strip() for p in parts if p.strip()]


def _top_keyword_pos(sql, kw):
    """Position of a top-level keyword outside strings/parens, else -1."""
    depth, quote, i, n = 0, None, 0, len(sql)
    kl = kw.lower()
    low = sql.lower()
    while i < n:
        ch = sql[i]
        if quote:
            if ch == quote:
                quote = None
            i += 1
            continue
        if ch in "'\"`":
            quote = ch
            i += 1
            continue
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
        elif depth == 0 and low.startswith(kl, i):
            before_ok = i == 0 or not (sql[i - 1].isalnum() or sql[i - 1] == "_")
            j = i + len(kl)
            after_ok = j >= n or not (sql[j].isalnum() or sql[j] == "_")
            if before_ok and after_ok:
                return i
        i += 1
    return -1


def _projection(sql):
    """(items, has_star, aggregate) of the outermost SELECT, or None."""
    low = sql.lstrip().lower()
    if not low.startswith("select"):
        return None
    if re.match(r"select\s+distinct\b", low):
        start = re.match(r"select\s+distinct\b", low).end()
    else:
        start = 6
    fpos = _top_keyword_pos(sql, "from")
    seg = sql[start:fpos] if fpos > start else sql[start:]
    items = _split_top(seg)
    if not items:
        return None
    star = any(it == "*" or re.match(r'^[\w".`\[\]]+\.\*$', it) for it in items)
    agg = bool(AGG_CALL.search(seg))
    return items, star, agg


def _named_attrs(question, schema):
    """Schema column names explicitly named (as words) in the question."""
    qwords = set(re.findall(r"[a-z]+", question.lower()))
    found = set()
    for cols in _tables(schema).values():
        for c in cols:
            toks = [t for t in re.split(r"[^a-z0-9]+", c.lower()) if t and not t.isdigit()]
            if not toks:
                continue
            if all(t in qwords for t in toks):
                found.add(c.lower())
            elif len(toks) > 1 and toks[-1] in ("name", "id", "code", "number", "date", "type"):
                # 'first name' / 'student id' style mentions of compound columns
                if all(t in qwords for t in toks[:-1]) and toks[-1] in qwords:
                    found.add(c.lower())
    return found


def _shape_feedback(task, env, schema, sql, res):
    """Detect wrong result SHAPE even when the query runs and returns rows."""
    fb = []
    question = task.get("question") or ""
    proj = _projection(sql)
    rows = res.get("rows") or []
    ncols = len(res.get("columns") or [])
    if proj and not proj[2] and not re.search(r"\bgroup\s+by\b", sql, re.I):
        items, star, _ = proj
        named = _named_attrs(question, schema)
        vague = bool(VAGUE_Q.search(question))
        if star and named and not vague:
            fb.append(
                "Projection looks too WIDE: your query returns %d columns (SELECT *), but the "
                "question explicitly names the attribute(s) it wants (%s). Select exactly the "
                "named attribute column(s) of the target table, in the order asked, nothing else."
                % (ncols, ", ".join(sorted(named)))
            )
        elif (not star) and ncols <= 2 and not named and (
            vague or re.search(r"\bwhich\s+\w+", question, re.I)
        ):
            tabs = _tables(schema)
            low = sql.lower()
            main = None
            m = re.search(r"\bfrom\s+[\"'`\[]?([A-Za-z_0-9]+)", low)
            if m:
                for t in tabs:
                    if t.lower() == m.group(1):
                        main = t
                        break
            extra = ""
            if main:
                star_sql = re.sub(
                    r"(?is)^(\s*select\s+(?:distinct\s+)?).*?(\s+from\s)",
                    lambda mm: mm.group(1) + "*" + mm.group(2),
                    sql,
                    count=1,
                )
                try:
                    r = env.execute(star_sql, max_rows=2)
                except Exception:
                    r = {"ok": False}
                if r.get("ok"):
                    extra = (
                        " For reference, the full records of the main table have %d columns: %s."
                        % (len(r.get("columns") or []), ", ".join(r.get("columns") or []))
                    )
            fb.append(
                "Projection may be too NARROW: your query returns only %d column(s), but the "
                "question asks about an entity without naming specific attributes. Reference "
                "answers for such questions usually return the FULL records (all columns) of "
                "the matching rows, including joined tables when a join is needed.%s If the "
                "question truly asks only for names/ids, keep the narrow projection; otherwise "
                "return the complete records." % (ncols, extra)
            )
    # Fan-out duplicates on entity-list questions.
    if (
        proj
        and not proj[2]
        and len(rows) >= 2
        and re.search(r"\bjoin\b", sql, re.I)
        and not re.search(r"\bdistinct\b|\bgroup\s+by\b|\bunion\b|\bexcept\b|\bintersect\b", sql, re.I)
        and not re.search(r"\bhow many\b|\bcount\b|\bnumber of\b|\btotal\b", question, re.I)
    ):
        try:
            uniq = len(set(tuple(r) for r in rows))
        except Exception:
            uniq = len(rows)
        if uniq < len(rows):
            fb.append(
                "Duplicate rows detected: the join fans out and your result repeats identical "
                "rows (%d returned vs %d distinct in the sample). If the question asks for a "
                "list of entities ('names for everybody', 'which ...'), each entity should "
                "appear once: add DISTINCT or use EXISTS/IN instead of the fan-out join. Keep "
                "duplicates only if the question asks for per-record output of the join itself."
                % (len(rows), uniq)
            )
    return fb


def solve(task, env):
    cfg = env.config or {}
    max_tokens = cfg.get("max_tokens", 800)
    schema = env.schema(task["db_id"])
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""

    user = "Database: %s\n\nSchema:\n%s\n" % (task["db_id"], schema)
    if desc.strip():
        user += "\nColumn descriptions:\n%s\n" % desc.strip()[:2500]
    user += "\nQuestion: %s" % task["question"]
    if task.get("hint"):
        user += "\nHint: %s" % task["hint"]
    user += "\n\nWrite the query now."

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=max_tokens)
    sql = extract_sql(reply)
    if not sql:
        return {"sql": sql}

    try:
        res = env.execute(sql, max_rows=20)
    except Exception:
        res = {"ok": False, "error": "execution failed", "rows": [], "n_rows": 0}

    ok = bool(res.get("ok"))
    nrows = res.get("n_rows", len(res.get("rows") or []))

    fb = []
    if not ok:
        fb = ["Your draft query was:", "```sql", sql, "```",
              "It failed to execute. Error: %s" % str(res.get("error"))[:400]]
    elif nrows == 0:
        fb = ["Your draft query was:", "```sql", sql, "```",
              "It executed but returned ZERO rows. That usually means a literal value does not "
              "match what is stored (spacing/casing/wording), a join key is wrong, or a NOT IN "
              "subquery contains NULLs. Re-read the question: an empty answer is rarely intended."]
    else:
        try:
            shape_fb = _shape_feedback(task, env, schema, sql, res)
        except Exception:
            shape_fb = []
        if shape_fb:
            fb = ["Your draft query was:", "```sql", sql, "```",
                  "It executed and returned %d row(s) x %d column(s), but its RESULT SHAPE may "
                  "not match what the question asks:" % (nrows, len(res.get("columns") or []))]
            fb.extend(shape_fb)

    if not fb:
        return {"sql": sql}

    if not ok or nrows == 0:
        samples = ""
        try:
            samples = _sample_values(env, schema, sql)
        except Exception:
            samples = ""
        if samples:
            fb.append("Actual stored values in the database:\n" + samples)
    fb.append(
        "Re-read the question and decide the exact projection and row set it asks for. Return "
        "the corrected query in a single ```sql block. Loosen string matching "
        "(LIKE '%keyword%' / lower(...)) when the exact value is unknown, use EXCEPT or "
        "NOT EXISTS for negation, select exactly the named attributes when the question names "
        "them, and full entity records when it asks about an entity without naming attributes."
    )

    messages = messages + [
        {"role": "assistant", "content": reply},
        {"role": "user", "content": "\n".join(fb)},
    ]
    try:
        reply2 = env.chat(messages, max_tokens=max_tokens)
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    try:
        res2 = env.execute(sql2, max_rows=5)
    except Exception:
        res2 = {"ok": False}
    if res2.get("ok"):
        return {"sql": sql2}
    return {"sql": sql if ok else sql2}

