                "Projection may be too NARROW: your query returns only %d column(s), but the "
                "question asks about an entity without naming specific attributes. Reference "
                "answers for such questions usually return the FULL records (all columns) of "
                "the matching rows, including joined tables when a join is needed.%s If the "
                "question truly asks only for names/ids, keep the narrow projection; otherwise "
                "return the complete records." % (ncols, extra)
            )
    # Fan-out duplicates on entity-list questions.
    if (
        proj
        and not proj[2]
        and len(rows) >= 2
        and re.search(r"\bjoin\b", sql, re.I)
        and not re.search(r"\bdistinct\b|\bgroup\s+by\b|\bunion\b|\bexcept\b|\bintersect\b", sql, re.I)
        and not re.search(r"\bhow many\b|\bcount\b|\bnumber of\b|\btotal\b", question, re.I)
    ):
        try:
            uniq = len(set(tuple(r) for r in rows))
        except Exception:
            uniq = len(rows)
        if uniq < len(rows):
            fb.append(
                "Duplicate rows detected: the join fans out and your result repeats identical "
                "rows (%d returned vs %d distinct in the sample). If the question asks for a "
                "list of entities ('names for everybody', 'which ...'), each entity should "
                "appear once: add DISTINCT or use EXISTS/IN instead of the fan-out join. Keep "
                "duplicates only if the question asks for per-record output of the join itself."
                % (len(rows), uniq)
            )
    return fb


def solve(task, env):
    cfg = env.config or {}
    max_tokens = cfg.get("max_tokens", 800)
    schema = env.schema(task["db_id"])
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""

    user = "Database: %s\n\nSchema:\n%s\n" % (task["db_id"], schema)
    if desc.strip():
        user += "\nColumn descriptions:\n%s\n" % desc.strip()[:2500]
    user += "\nQuestion: %s" % task["question"]
    if task.get("hint"):
        user += "\nHint: %s" % task["hint"]
    user += "\n\nWrite the query now."

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=max_tokens)
    sql = extract_sql(reply)
    if not sql:
        return {"sql": sql}

    try:
        res = env.execute(sql, max_rows=20)
    except Exception:
        res = {"ok": False, "error": "execution failed", "rows": [], "n_rows": 0}

    ok = bool(res.get("ok"))
    nrows = res.get("n_rows", len(res.get("rows") or []))

    fb = []
    if not ok:
        fb = ["Your draft query was:", "```sql", sql, "```",
              "It failed to execute. Error: %s" % str(res.get("error"))[:400]]
    elif nrows == 0:
        fb = ["Your draft query was:", "```sql", sql, "```",
              "It executed but returned ZERO rows. That usually means a literal value does not "
              "match what is stored (spacing/casing/wording), a join key is wrong, or a NOT IN "
              "subquery contains NULLs. Re-read the question: an empty answer is rarely intended."]
    else:
        try:
            shape_fb = _shape_feedback(task, env, schema, sql, res)
        except Exception:
            shape_fb = []
        if shape_fb:
            fb = ["Your draft query was:", "```sql", sql, "```",
                  "It executed and returned %d row(s) x %d column(s), but its RESULT SHAPE may "
                  "not match what the question asks:" % (nrows, len(res.get("columns") or []))]
            fb.extend(shape_fb)

    if not fb:
        return {"sql": sql}

    if not ok or nrows == 0:
        samples = ""
        try:
            samples = _sample_values(env, schema, sql)
        except Exception:
            samples = ""
        if samples:
            fb.append("Actual stored values in the database:\n" + samples)
    fb.append(
        "Re-read the question and decide the exact projection and row set it asks for. Return "
        "the corrected query in a single ```sql block. Loosen string matching "
        "(LIKE '%keyword%' / lower(...)) when the exact value is unknown, use EXCEPT or "
        "NOT EXISTS for negation, select exactly the named attributes when the question names "
        "them, and full entity records when it asks about an entity without naming attributes."
    )

    messages = messages + [
        {"role": "assistant", "content": reply},
        {"role": "user", "content": "\n".join(fb)},
    ]
    try:
        reply2 = env.chat(messages, max_tokens=max_tokens)
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    try:
        res2 = env.execute(sql2, max_rows=5)
    except Exception:
        res2 = {"ok": False}
    if res2.get("ok"):
        return {"sql": sql2}
    return {"sql": sql if ok else sql2}
